function offerPct(old,cur){const a=firstNum(old),b=firstNum(cur);return(a>0&&b>0&&a>b)?Math.round((a-b)/a*100):0}
function fmtEnds(d){const m=String(d||'').match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return'';return(+m[3])+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][+m[2]-1]+' '+m[1]}
function offerHTML(o,pr,withCta){const st=['gold','purple','green','red','blue'].includes(o.style)?o.style:'gold';const showP=pr&&pr.show&&pr.premium;const pct=showP&&o.old?offerPct(o.old,pr.premium):0;const ends=fmtEnds(o.ends);return `<div class="offer3d of-${st}" role="region" aria-label="Special offer">${o.badge?`<span class="of-badge">${esc(o.badge)}</span>`:''}<span class="of-text">${esc(o.text)}</span>${showP?`<span class="of-price">${o.old?`<s aria-label="Old price">${esc(o.old)}</s>`:''}<b>${esc(pr.premium)}</b>${pct?`<span class="of-off">${pct}% OFF</span>`:''}</span>`:''}${ends?`<span class="of-ends">Offer ends ${esc(ends)}</span>`:''}${withCta?`<span class="of-cta"><a href="builder.html">Get this offer</a></span>`:''}</div>`}
function renderOffer(){const el=document.getElementById('offerBanner');if(!el)return;el.innerHTML=offerActive(BUSINESS.offer)?offerHTML(BUSINESS.offer,BUSINESS.prices,!/builder\.html/.test(location.pathname)):''}
let builderActive=false;
function persistNow(){if(!builderActive)return;clearTimeout(saveTimer);try{localStorage.setItem('cvStudioAuto',JSON.stringify(state))}catch(e){try{localStorage.setItem('cvStudioAuto',JSON.stringify(Object.assign({},state,{photo:'',photoThumb:''})))}catch(e2){}}}
function saveAuto(){clearTimeout(saveTimer);saveTimer=setTimeout(persistNow,250)}
window.addEventListener('pagehide',persistNow);window.addEventListener('beforeunload',persistNow);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persistNow()});
function loadAuto(){try{const r=localStorage.getItem('cvStudioAuto');if(r){state=Object.assign(blank(),JSON.parse(r));const bl=blank();state.form=Object.assign(bl.form,state.form||{});if(!Array.isArray(state.form.expMore))state.form.expMore=[];if(!Array.isArray(state.form.eduMore))state.form.eduMore=[];state.show=Object.assign(bl.show,state.show||{})}state.theme=cleanTheme(state.theme,blank().theme);if(state.form&&Array.isArray(state.form.tech))state.form.tech=state.form.tech.map(x=>({name:String(x&&x.name||''),level:pct(x&&x.level)}));}catch(e){}}
function setField(path,val){let o=state;const p=path.split('.');for(let i=0;i<p.length-1;i++)o=o[p[i]];o[p[p.length-1]]=val;saveAuto();refreshPreview()}
function setStep(n){state.step=n;fullRender();setTimeout(()=>document.querySelector('.formpanel')?.scrollTo({top:0,behavior:'smooth'}),20)}
function fullRender(){const el=document.getElementById('builderApp');if(el){el.innerHTML=builderHTML();try{boxify()}catch(e){}syncPrintLock();refreshPreview()}}
function fullRenderKeepPosition(){const y=window.scrollY;const panel=document.querySelector('.formpanel');const py=panel?panel.scrollTop:0;fullRender();requestAnimationFrame(()=>{window.scrollTo(0,y);const p=document.querySelector('.formpanel');if(p)p.scrollTop=py;})}

