var BOX_ICO={bolt:'<path d="M13 3 5 13h6l-1 8 8-10h-6z"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18c1.4 0 2-1 1.5-2.2-.5-1.2.2-2.3 1.5-2.3H17a4 4 0 0 0 4-4C21 6.5 17 3 12 3z"/><circle cx="7.5" cy="11" r="1"/><circle cx="10" cy="7.5" r="1"/><circle cx="14.5" cy="7.5" r="1"/>',import:'<path d="M12 4v11"/><path d="m7 10 5 5 5-5"/><path d="M5 20h14"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.5-6 8-6s8 2 8 6"/>',camera:'<path d="M4 8h3l2-3h6l2 3h3v11H4z"/><circle cx="12" cy="13" r="3.5"/>',brief:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M9 7V5h6v2"/><path d="M3 13h18"/>',cap:'<path d="m2 9 10-5 10 5-10 5z"/><path d="M6 11.5V16c3 2.5 9 2.5 12 0v-4.5"/>',tools:'<path d="M14 6a4 4 0 0 0 5 5l-9 9a2.1 2.1 0 0 1-3-3l9-9a4 4 0 0 0-2-2z"/>',plus:'<circle cx="12" cy="12" r="9"/><path d="M12 8v8M8 12h8"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',save:'<path d="M5 3h12l3 3v15H5z"/><path d="M8 3v6h8V3"/><rect x="8" y="14" width="8" height="7"/>',wrench:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',id:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="11" r="2"/><path d="M6 16c.5-2 5.5-2 6 0M14 10h4M14 14h4"/>',sliders:'<path d="M4 6h10M18 6h2M4 12h4M12 12h8M4 18h12M20 18h0"/><circle cx="16" cy="6" r="2"/><circle cx="10" cy="12" r="2"/><circle cx="18" cy="18" r="2"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1L3.2 9.5l6.1-.9z"/>',pin:'<path d="M12 21s7-6 7-11a7 7 0 0 0-14 0c0 5 7 11 7 11z"/><circle cx="12" cy="10" r="2.5"/>'};function boxIco(k){return '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+(BOX_ICO[k]||BOX_ICO.pin)+'</svg>'}
var BOX_META={'Quick start':['bolt','Type your own details or see an example'],'Choose Template':['palette','Tap a design picture. You can change it later'],'Import old resume text':['import','Paste old CV text to fill basic details'],'Personal Details':['user','Name, phone, email and a short summary'],'Profile Photo':['camera','Optional. Zoom, move and flip your photo'],'Experience':['brief','Your jobs, newest first'],'Education':['cap','Degrees and certificates'],'Skills':['tools','What you are good at'],'Extra Sections':['plus','Projects, certifications, references'],'Show / Hide Sections':['eye','Switch CV sections on or off'],'Change Template Anytime':['palette','Pick another design. Your data stays safe'],'Save Work':['save','Save or load your work on this device'],'Owner Order Tools':['wrench','Owner only'],'Personal Information (optional)':['id','CNIC, date of birth, father name. Only if the employer asks'],'Custom Theme Premium':['sliders','Change CV colours (premium)'],'CV Health Check':['check','Quick check before you download'],'Premium selected':['star','About your premium design'],'Text Style':['sliders','Font, text size, spacing and bold headings'],'Download your CV':['import','3 easy steps. Your PDF is ready in a minute'],'Unlock your premium CV':['star','Pay, send order, get your code. Simple steps'],'See your CV in a premium design':['star','Preview only. Your free design is kept'],'Previewing a premium design':['star','Go back to your free design anytime']};
var BOX_STATE={};function bkey(t){return t==='Unlock your premium CV'?'Download your CV':t}
function boxify(){
  var root=document.querySelector('.formpanel');if(!root)return;
  var step=String(state.step);var secs=[].filter.call(root.querySelectorAll('.formsec'),function(e){return !e.parentElement.closest('.formsec')&&e.firstElementChild&&e.firstElementChild.tagName==='H3'});
  if(secs.length<2)return;
  if(!BOX_STATE[step]){BOX_STATE[step]={};var first=step==='1'?2:1;secs.slice(0,first).forEach(function(s){BOX_STATE[step][bkey(s.firstElementChild.textContent.trim())]=1})}
  secs.forEach(function(s,i){
    var h3=s.firstElementChild,title=h3.textContent.trim(),m=BOX_META[title]||['pin',''];
    var body=document.createElement('div');body.className='box-body';
    while(h3.nextSibling)body.appendChild(h3.nextSibling);
    var next=secs[i+1];
    if(next){var nt=next.firstElementChild.textContent.trim();var nb=document.createElement('button');nb.type='button';nb.className='btn light box-next';nb.setAttribute('data-next',nt);nb.textContent='Next: '+nt+' ▸';body.appendChild(nb)}
    var head=document.createElement('button');head.type='button';head.className='box-head';head.setAttribute('data-box',title);
    var open=!!BOX_STATE[step][bkey(title)];head.setAttribute('aria-expanded',open?'true':'false');
    head.innerHTML='<span class="box-ico" aria-hidden="true">'+boxIco(m[0])+'</span><span class="box-tt"><b></b><small></small></span><span class="box-chev" aria-hidden="true">▾</span>';
    head.querySelector('b').textContent=title;head.querySelector('small').textContent=m[1];
    h3.remove();s.classList.add('box');if(open)s.classList.add('open');
    s.insertBefore(head,s.firstChild);s.appendChild(body);
  });
}
document.addEventListener('click',function(e){
  var nb=e.target.closest&&e.target.closest('.box-next');var h=e.target.closest&&e.target.closest('.box-head');
  if(!nb&&!h)return;
  var step=String(state.step);BOX_STATE[step]=BOX_STATE[step]||{};
  var target=null;
  if(h){var t=h.getAttribute('data-box');var s=h.parentElement;var open=!s.classList.contains('open');BOX_STATE[step][bkey(t)]=open?1:0;s.classList.toggle('open',open);h.setAttribute('aria-expanded',open?'true':'false');if(open)target=s}
  else{var cur=nb.closest('.box');if(cur){cur.classList.remove('open');var ch=cur.querySelector('.box-head');ch.setAttribute('aria-expanded','false');BOX_STATE[step][bkey(ch.getAttribute('data-box'))]=0}
    var nt=nb.getAttribute('data-next');var all=document.querySelectorAll('.box-head');for(var i=0;i<all.length;i++){if(all[i].getAttribute('data-box')===nt){var ns=all[i].parentElement;ns.classList.add('open');all[i].setAttribute('aria-expanded','true');BOX_STATE[step][bkey(nt)]=1;target=ns;break}}}
  if(target&&target.scrollIntoView)setTimeout(function(){target.scrollIntoView({behavior:'smooth',block:'start'})},30);
});
