function sumCat(job){const j=' '+String(job||'').toLowerCase()+' ';for(const c of SUM_CATS)if(c.k.test(j))return c;return {area:'my field',skills:['teamwork','time management','clear communication','learning new tools quickly']}}
function cleanSkill(n){return String(n||'').replace(/\(.*?\)/g,'').replace(/\s+/g,' ').trim()}
function sumVariants(job,years,s1,s2,area){const J=job,a=/^[aeiou]/i.test(J)?'an':'a';const y=Number(years);const yr=y>=1?`${y} year${y>1?'s':''} of experience`:'';const exp=y>=1;const list=[
 {e:true,t:`${J} with ${yr} in ${area}. Comfortable with ${s1} and ${s2}, and known for finishing work accurately and on time.`},
 {e:false,t:`I am ${a} ${J.toLowerCase()} who enjoys ${area}. My strengths are ${s1}, ${s2} and staying organised when the workload is high.`},
 {e:false,t:`${J} looking for a role where I can use my skills in ${s1} and ${s2}, and keep learning on the job.`},
 {e:true,t:`Dependable ${J.toLowerCase()} with ${yr}. I handle day-to-day ${area} carefully and communicate clearly with colleagues and clients.`},
 {e:false,t:`${J} with working knowledge of ${s1} and ${s2}. I follow instructions properly, take responsibility for my work and ask questions when something is unclear.`},
 {e:false,t:`Practical, hard-working ${J.toLowerCase()}. I prefer steady, accurate work in ${area} and can adapt quickly to new tools, teams and routines.`},
 {e:true,t:`${J} with ${yr}, including ${s1} and ${s2}. I keep records tidy, meet deadlines and support my team when needed.`},
 {e:false,t:`Entry-level ${J.toLowerCase()} trained in ${s1} and ${s2}. Eager to gain real workplace experience, learn from seniors and grow with the company.`,f:true},
 {e:false,t:`${J} who values punctuality, honesty and clear communication. Skilled in ${s1} and ${s2}, with a steady approach to ${area}.`},
 {e:false,t:`Detail-focused ${J.toLowerCase()}, comfortable working independently or in a team. Able to take on ${area} responsibilities, learn new systems quickly and keep standards high.`},
 {e:true,t:`${J} with ${yr} in ${area}. I focus on reliable day-to-day delivery, good teamwork and learning something new on every project.`}
];return list.filter(v=>exp?(v.e||(!v.f)):(!v.e))}
function aiSummary(){const f=state.form;const job=(f.job||'').trim()||'Professional';const cat=sumCat(f.job);const have=(f.tech||[]).map(x=>cleanSkill(x.name)).filter(Boolean);const s1=have[0]||cat.skills[0],s2=have[1]||cat.skills[1];const vars=sumVariants(job,f.years,s1,s2,cat.area);state.sumIdx=((Number(state.sumIdx)||0)+1)%vars.length;const pick=vars[state.sumIdx];f.summary=pick.t.replace(/\s{2,}/g,' ');saveAuto();const field=document.getElementById('summaryField');if(field){field.value=f.summary;field.focus()}refreshPreview();const n=document.getElementById('sumCount');if(n)n.textContent=`Suggestion ${state.sumIdx+1} of ${vars.length}. Press again for another one.`}
