function orderStep(n){[1,2,3].forEach(i=>{var p=document.getElementById('payPane'+i),t=document.getElementById('payTab'+i);if(p)p.classList.toggle('on',i===n);if(t){t.classList.toggle('on',i===n);t.setAttribute('aria-selected',i===n?'true':'false')}})}function openOrder(){orderStep(1);document.getElementById('paywall').style.display='flex';try{loadPayment()}catch(e){}}function closeOrder(){document.getElementById('paywall').style.display='none'}function whatsappOrder(){const f=state.form;if(!f.name.trim()||!f.phone.trim()){alert('Please fill your Name and Phone Number before sending the order, so we can contact you.');closeOrder();setStep(2);return}const btn=document.getElementById('sendOrderBtn');if(btn){if(btn.dataset.sent==='1')return;btn.dataset.sent='1';btn.disabled=true;btn.textContent='Order Sent - Check WhatsApp';setTimeout(()=>{btn.disabled=false;btn.dataset.sent='0';btn.textContent='Send Order on WhatsApp'},6000)}const w=window.open(`https://wa.me/${BUSINESS.whatsapp}?text=${encodeURIComponent(orderText())}`,'_blank');if(!w||w.closed||typeof w.closed==='undefined'){alert('Your browser blocked the WhatsApp popup. Please allow popups for this site and press the order button again.')}}
async function submitOrderOnline(){const f=state.form;if(!f.name.trim()||!f.phone.trim()){alert('Please fill your Name and Phone Number before submitting the order, so we can contact you.');closeOrder();setStep(2);return}const btn=document.getElementById('submitOrderBtn');if(btn){if(btn.dataset.sent==='1')return;btn.dataset.sent='1';btn.disabled=true;btn.textContent='Submitting...'}const txn=(document.getElementById('txnInput')||{}).value||'';const result=await verifyWithBackend({action:'submitOrder',name:f.name,whatsapp:f.phone,email:f.email,template:state.template,txn:txn,note:'Submitted online from builder'});if(btn){btn.disabled=false}if(result&&result.valid){if(btn){btn.textContent='Order Submitted - Check Email Soon';setTimeout(()=>{btn.dataset.sent='0';btn.textContent='Submit Order Online'},6000)}showOrderDone(result.orderNo||'')}else{if(btn){btn.dataset.sent='0';btn.textContent='Submit Order Online'}alert('Could not submit your order online right now. Please use "Send Order on WhatsApp" instead, or check your internet connection.')}}
