/* Editable Word (.docx): simple text-based CV built from the form data (no design, no photo). Self-contained: tiny store-only ZIP writer, no libraries. */
function docxZip(files){const enc=new TextEncoder(),tab=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;tab[n]=c>>>0}const crc=b=>{let c=0xFFFFFFFF;for(let i=0;i<b.length;i++)c=tab[(c^b[i])&255]^(c>>>8);return (c^0xFFFFFFFF)>>>0};const parts=[],cen=[];let off=0;const d=new Date(),dt=((d.getHours()<<11)|(d.getMinutes()<<5)|(d.getSeconds()>>1))&0xFFFF,dd=(((d.getFullYear()-1980)<<9)|((d.getMonth()+1)<<5)|d.getDate())&0xFFFF;files.forEach(f=>{const nm=enc.encode(f.name),data=enc.encode(f.data),cr=crc(data);const lh=new DataView(new ArrayBuffer(30));lh.setUint32(0,0x04034b50,true);lh.setUint16(4,20,true);lh.setUint16(6,0x0800,true);lh.setUint16(8,0,true);lh.setUint16(10,dt,true);lh.setUint16(12,dd,true);lh.setUint32(14,cr,true);lh.setUint32(18,data.length,true);lh.setUint32(22,data.length,true);lh.setUint16(26,nm.length,true);lh.setUint16(28,0,true);parts.push(new Uint8Array(lh.buffer),nm,data);const ch=new DataView(new ArrayBuffer(46));ch.setUint32(0,0x02014b50,true);ch.setUint16(4,20,true);ch.setUint16(6,20,true);ch.setUint16(8,0x0800,true);ch.setUint16(10,0,true);ch.setUint16(12,dt,true);ch.setUint16(14,dd,true);ch.setUint32(16,cr,true);ch.setUint32(20,data.length,true);ch.setUint32(24,data.length,true);ch.setUint16(28,nm.length,true);ch.setUint32(42,off,true);cen.push(new Uint8Array(ch.buffer),nm);off+=30+nm.length+data.length});let cs=0;cen.forEach(c=>cs+=c.length);const ed=new DataView(new ArrayBuffer(22));ed.setUint32(0,0x06054b50,true);ed.setUint16(8,files.length,true);ed.setUint16(10,files.length,true);ed.setUint32(12,cs,true);ed.setUint32(16,off,true);return new Blob(parts.concat(cen,[new Uint8Array(ed.buffer)]),{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
function docxXml(){const f=state.form,X=v=>String(v==null?'':v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),T=v=>String(v==null?'':v).trim();
 const run=(t,o={})=>`<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/>${o.b?'<w:b/>':''}${o.i?'<w:i/>':''}${o.c?`<w:color w:val="${o.c}"/>`:''}<w:sz w:val="${o.sz||21}"/></w:rPr><w:t xml:space="preserve">${X(t)}</w:t></w:r>`;
 const para=(runs,o={})=>`<w:p><w:pPr>${o.keep?'<w:keepNext/>':''}${o.border?'<w:pBdr><w:bottom w:val="single" w:sz="6" w:space="1" w:color="808080"/></w:pBdr>':''}<w:spacing w:before="${o.before||0}" w:after="${o.after==null?60:o.after}"/>${o.bullet?'<w:ind w:left="360" w:hanging="220"/>':''}${o.center?'<w:jc w:val="center"/>':''}</w:pPr>${runs}</w:p>`;
 const accent=(safeColor(state.theme.main,'#1e3a8a')||'#1e3a8a').replace('#','').slice(0,6);let body='';
 const head=t=>{body+=para(run(t.toUpperCase(),{b:1,sz:23,c:accent}),{before:200,after:80,border:1,keep:1})};
 const lines=v=>String(v||'').split(/\n+/).map(T).filter(Boolean);
 const bullets=v=>{lines(v).forEach(l=>{body+=para(run('• '+l),{bullet:1,after:30})})};
 const entries=list=>list.forEach(x=>{if(T(x.t))body+=para(run(x.t,{b:1}),{after:0,keep:1,before:80});if(T(x.c))body+=para(run(x.c,{i:1,c:'555555'}),{after:30,keep:1});const L=lines(x.d);if(L.length===1)body+=para(run(L[0]));else bullets(x.d)});
 body+=para(run(f.name||'Your Name',{b:1,sz:40,c:accent}),{after:20});if(T(f.job))body+=para(run(f.job,{sz:26,c:'444444'}),{after:40});const ct=[f.phone,f.email,f.address].map(T).filter(Boolean).join('  |  ');if(ct)body+=para(run(ct,{sz:20}),{after:80});
 const exp=[{t:f.exp1t,c:f.exp1c,d:f.exp1d},{t:f.exp2t,c:f.exp2c,d:f.exp2d}].concat(Array.isArray(f.expMore)?f.expMore:[]).filter(x=>x&&(T(x.t)||T(x.c)||T(x.d)));
 const edu=[{t:f.edu1t,c:f.edu1c,d:f.edu1d},{t:f.edu2t,c:f.edu2c,d:f.edu2d}].concat(Array.isArray(f.eduMore)?f.eduMore:[]).filter(x=>x&&(T(x.t)||T(x.c)||T(x.d)));
 const S=state.show;if(S.summary&&T(f.summary)){head('Summary');body+=para(run(f.summary))}
 const persB=()=>{if(S.personal){const r=personalRows();if(r.length){head('Personal Information');r.forEach(x=>{body+=para(run(x[0]+': ',{b:1})+run(x[1]),{after:20})})}}};
 const expB=()=>{if(S.experience&&exp.length){head('Experience');entries(exp);if(T(f.achievements)){head('Key Achievements');bullets(f.achievements)}}};
 const eduB=()=>{if(S.education&&edu.length){head('Education');entries(edu)}};
 persB();eduB();expB()
 const tech=(f.tech||[]).map(x=>T(x&&x.name)).filter(Boolean);if(S.tech&&tech.length){head('Technical Skills');body+=para(run(tech.join(', ')))}
 if(S.soft&&splitList(f.soft).length){head('Soft Skills');body+=para(run(splitList(f.soft).join(', ')))}
 if(S.lang&&splitList(f.lang).length){head('Languages');body+=para(run(splitList(f.lang).join(', ')))}
 if(S.projects&&T(f.projects)){head('Projects');bullets(String(f.projects).replace(/\|/g,'\n'))}
 if(S.certs&&T(f.certs)){head('Certifications');bullets(String(f.certs).replace(/\|/g,'\n'))}
 if(S.custom&&T(f.customTitle)&&T(f.customBody)){head(f.customTitle);body+=para(run(f.customBody))}
 if(S.refs&&T(f.refs)){head('References');body+=para(run(f.refs))}
 return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1000" w:right="1000" w:bottom="1000" w:left="1000" w:header="500" w:footer="500" w:gutter="0"/></w:sectPr></w:body></w:document>`}
function exportDocx(){if(isPremium()&&!ownerMode&&!customerUnlocked()){openOrder();return}try{const blob=docxZip([{name:'[Content_Types].xml',data:'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'},{name:'_rels/.rels',data:'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'},{name:'word/document.xml',data:docxXml()}]);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(state.form.name||'cv').replace(/[^\w\-]+/g,'_')+'.docx';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1500)}catch(e){alert('Word export failed. Please try Print / Save PDF instead.')}}
async function exportWord(){if(isPremium()&&!ownerMode&&!customerUnlocked()){openOrder();return}const pages=document.querySelectorAll('#cvPreview .cvpage');if(!pages.length){alert('CV preview not ready yet. Please wait a moment and try again.');return}const btn=document.getElementById('wordBtn');if(btn){btn.disabled=true;btn.textContent='Preparing Word file...'}try{if(typeof html2canvas==='undefined'){alert('Export tool is still loading. Please check your internet connection and try again in a few seconds.');return}let imgsHTML='';for(let i=0;i<pages.length;i++){const pg=pages[i];const canvas=await html2canvas(pg,{scale:2,useCORS:true,backgroundColor:'#ffffff'});const dataUrl=canvas.toDataURL('image/jpeg',0.92);imgsHTML+=`<div style="page-break-after:${i===pages.length-1?'auto':'always'};page-break-inside:avoid"><img src="${dataUrl}" style="width:100%;display:block"></div>`}const blob=new Blob([`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>CV</title></head><body>${imgsHTML}</body></html>`],{type:'application/msword'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(state.form.name||'cv').replace(/\s+/g,'_')+'.doc';a.click()}catch(e){alert('Word export failed. Please try Print / Save PDF instead, or try again in a few seconds.')}finally{if(btn){btn.disabled=false;btn.textContent='Download Word'}}}
