function importStructured(){const txt=state.form.pasteOrder||'';const map={};txt.split('\n').forEach(l=>{const i=l.indexOf(':');if(i>0)map[l.slice(0,i).trim()]=l.slice(i+1).trim()});const f=state.form;f.name=map.NAME||f.name;f.job=map.JOB_TITLE||f.job;f.phone=map.PHONE||f.phone;f.email=map.EMAIL||f.email;f.address=map.ADDRESS||f.address;f.summary=map.SUMMARY||f.summary;f.soft=map.SOFT_SKILLS||f.soft;f.lang=map.LANGUAGES||f.lang;f.exp1t=map.EXPERIENCE_1_TITLE||f.exp1t;f.exp1c=map.EXPERIENCE_1_COMPANY||f.exp1c;f.exp1d=map.EXPERIENCE_1_DESC||f.exp1d;f.exp2t=map.EXPERIENCE_2_TITLE||f.exp2t;f.exp2c=map.EXPERIENCE_2_COMPANY||f.exp2c;f.exp2d=map.EXPERIENCE_2_DESC||f.exp2d;f.edu1t=map.EDUCATION_1_TITLE||f.edu1t;f.edu1c=map.EDUCATION_1_INSTITUTE||f.edu1c;f.edu1d=map.EDUCATION_1_DESC||f.edu1d;f.edu2t=map.EDUCATION_2_TITLE||f.edu2t;f.edu2c=map.EDUCATION_2_INSTITUTE||f.edu2c;f.edu2d=map.EDUCATION_2_DESC||f.edu2d;f.father=map.FATHER_NAME||f.father;f.dob=map.DATE_OF_BIRTH||f.dob;f.cnic=map.CNIC||f.cnic;f.marital=map.MARITAL_STATUS||f.marital;f.nationality=map.NATIONALITY||f.nationality;f.domicile=map.DOMICILE||f.domicile;f.religion=map.RELIGION||f.religion;if(map.PERSONAL_INFO_SHOWN)state.show.personal=(map.PERSONAL_INFO_SHOWN.toLowerCase()==='yes');f.expMore=[];f.eduMore=[];for(let n=3;n<=10;n++){if(map['EXPERIENCE_'+n+'_TITLE']||map['EXPERIENCE_'+n+'_COMPANY']||map['EXPERIENCE_'+n+'_DESC'])f.expMore.push({t:map['EXPERIENCE_'+n+'_TITLE']||'',c:map['EXPERIENCE_'+n+'_COMPANY']||'',d:map['EXPERIENCE_'+n+'_DESC']||''});if(map['EDUCATION_'+n+'_TITLE']||map['EDUCATION_'+n+'_INSTITUTE']||map['EDUCATION_'+n+'_DESC'])f.eduMore.push({t:map['EDUCATION_'+n+'_TITLE']||'',c:map['EDUCATION_'+n+'_INSTITUTE']||'',d:map['EDUCATION_'+n+'_DESC']||''})}f.achievements=map.ACHIEVEMENTS||f.achievements||'';f.projects=map.PROJECTS||f.projects;f.certs=map.CERTIFICATIONS||f.certs;f.refs=map.REFERENCES||f.refs;f.customTitle=map.CUSTOM_TITLE||f.customTitle;f.customBody=map.CUSTOM_BODY||f.customBody;if(map.PHOTO_BASE64&&map.PHOTO_BASE64.startsWith('data:image')){state.photo=map.PHOTO_BASE64;state.photoThumb=map.PHOTO_BASE64}if(map.TEMPLATE){const found=templates.find(t=>t.name.toLowerCase()===map.TEMPLATE.toLowerCase());if(found)state.template=found.id}fullRenderKeepPosition();alert(map.PHOTO_BASE64?'Order imported successfully, including photo.':'Order imported. No photo was found in this order text.')}
function importResume(){const txt=state.form.pasteResume||'';if(!txt.trim()){alert('Paste resume text first');return}const email=txt.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);const phone=txt.match(/(?:\+?92|0)?3\d{2}[\s-]?\d{7}/);const lines=txt.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!state.form.name&&lines[0])state.form.name=lines[0];if(email)state.form.email=email[0];if(phone)state.form.phone=phone[0];if(!state.form.summary)state.form.summary=lines.slice(1,4).join(' ');fullRenderKeepPosition()}
function setPhotoFit(k,v){state.photoFit[k]=Number(v);saveAuto();refreshPreview()}function photoStyle(){const x=Number(state.photoFit.x)||50;const y=Number(state.photoFit.y)||50;const zoom=Number(state.photoFit.zoom)||1;const tx=(x-50)*0.7;const ty=(y-50)*0.7;return `--photo-zoom:${zoom};--photo-x:${x}%;--photo-y:${y}%;--photo-tx:${tx}%;--photo-ty:${ty}%`}
function photoFrameHTML(){const unlocked=true;const f=state.photoFrame;const shapes=[   ['circle','Circle'],   ['rounded','Rounded'],   ['square','Square'],   ['soft','Soft Card'],   ['double','Double Ring'],   ['hex','Hexagon'],   ['diamond','Diamond'],   ['arch','Arch'],   ['blob','Blob'],   ['leaf','Leaf'],   ['ring','Ring'],   ['squircle','Squircle'],   ['cut','Cut Corner'],   ['pill','Pill'],   ['polaroid','Polaroid'] ];const lockNote='<p class="muted small">Try any frame and see it live. A custom frame is a premium design, so downloading needs an access code.</p>';return `<div class="formsec photo-frame-box"><h3>Photo Frame</h3>${lockNote}<div class="row"><div><label>Frame Shape</label><div class="actions">${shapes.map(([v,l])=>`<button class="btn ${f.shape===v?'dark':'light'}" onclick="setPhotoFrame('shape','${v}')">${l}</button>`).join('')}</div></div></div><div class="row"><div><label class="sw"><input type="checkbox" ${f.outline?'checked':''} onchange="setPhotoFrame('outline',this.checked)"><span class="sw-track" aria-hidden="true"></span><span class="sw-text"><b>Show outline</b><small>Coloured line around the photo</small></span></label></div><div>${f.outline?`<label>Outline Color</label><input type="color" value="${safeColor(f.outlineColor,'#2563eb')}" onchange="setPhotoFrame('outlineColor',this.value)">`:''}</div></div></div>`}
function setPhotoFrame(key,value){state.frameTouched=true;state.photoFrame[key]=value;saveAuto();fullRenderKeepPosition()}function handlePhoto(input){
  const file=input.files?.[0];
  if(!file)return;

  if(!file.type.startsWith('image/')){
    alert('Please choose an image file (JPG or PNG).');
    return;
  }

  const reader=new FileReader();

  reader.onload=()=>{
    const data=reader.result;

    state.photo=data;
    state.photoThumb=data;

    // IMPORTANT:
    // Do not rebuild the whole builder here.
    refreshPreview();
    saveAuto();

    const img=new Image();

    img.onload=()=>{
      try{
        const maxSize=700;
        let w=img.width;
        let h=img.height;

        if(w>h && w>maxSize){
          h=Math.round(h*(maxSize/w));
          w=maxSize;
        }else if(h>maxSize){
          w=Math.round(w*(maxSize/h));
          h=maxSize;
        }

        const canvas=document.createElement('canvas');
        canvas.width=w;
        canvas.height=h;

        const ctx=canvas.getContext('2d');

        if(ctx){
          ctx.drawImage(img,0,0,w,h);
          state.photo=canvas.toDataURL('image/jpeg',0.82);
        }

        let tw=img.width;
        let th=img.height;
        const tMax=260;

        if(tw>th && tw>tMax){
          th=Math.round(th*(tMax/tw));
          tw=tMax;
        }else if(th>tMax){
          tw=Math.round(tw*(tMax/th));
          th=tMax;
        }

        const tCanvas=document.createElement('canvas');
        tCanvas.width=tw;
        tCanvas.height=th;

        const tCtx=tCanvas.getContext('2d');

        if(tCtx){
          tCtx.drawImage(img,0,0,tw,th);
          state.photoThumb=tCanvas.toDataURL('image/jpeg',0.6);
        }

        saveAuto();
        refreshPreview();

      }catch(e){
        console.error('Photo processing failed:',e);
        saveAuto();
        refreshPreview();
      }
    };

    img.onerror=()=>{
      console.warn('Photo optimization failed. Original photo will be used.');
      saveAuto();
      refreshPreview();
    };

    img.src=data;
  };

  reader.onerror=()=>{
    alert('This photo could not be read. Please try another JPG or PNG file.');
  };

  reader.readAsDataURL(file);
}
const TEMPLATES_WITH_DEFAULT_FRAME=['t65','t66','t67','t52','t53','t54','t55','t56','t57','t58','t59','t60','t61','t62','t63','t64','t34','t35','t36','t37','t38','t39','t40','t41','t1','t2','t3','t4','t5','t6','t7','t8','t9','t10','t11','t12','t13','t14','t15','t16','t17','t18','t19','t20','t21','t22','t23','t24'];
function photoFor(pos,circle=false){
  if(state.photoPlacement==='none')return'';
  if(state.photoPlacement!=='auto'&&state.photoPlacement!==pos)return'';

  const canCustomize=customerUnlocked()||ownerMode||!!state.frameTouched;
  const hasOwnDefaultFrame=TEMPLATES_WITH_DEFAULT_FRAME.includes(state.template);
  let extraStyle='';
  let cls=circle?'circle':'';

  const x=Number(state.photoFit.x)||50;
  const y=Number(state.photoFit.y)||50;
  const zoom=Number(state.photoFit.zoom)||1;

  const tx=(x-50)*0.7;
  const ty=(y-50)*0.7;

  if(canCustomize||hasOwnDefaultFrame){
    const f=state.photoFrame;const accentC=safeColor(state.theme&&state.theme.accent,'#2563eb');
    const outlineColor=safeColor(f.outlineColor,'#2563eb');
    const hasOutline=!!f.outline;
    let radius='16px',wh='',clip='',shadow='';
    let borderStyle=hasOutline?`border:4px solid ${outlineColor};`:'border:3px solid rgba(255,255,255,.85);';

    if(f.shape==='circle'){
      radius='50%';wh='width:96px;height:96px;';
    }else if(f.shape==='square'){
      radius='0';wh='width:96px;height:96px;';
    }else if(f.shape==='rounded'){
      radius='16px';wh='width:96px;height:112px;';
    }else if(f.shape==='soft'){
      radius='22px';wh='width:96px;height:112px;';
      shadow='box-shadow:0 14px 30px rgba(15,23,42,.22);';
      borderStyle=hasOutline?`border:5px solid ${outlineColor};`:'border:6px solid #fff;';
    }else if(f.shape==='double'){
      radius='50%';wh='width:96px;height:96px;';
      borderStyle='border:3px solid #fff;';
      shadow=`box-shadow:0 0 0 3px #fff,0 0 0 7px ${hasOutline?outlineColor:'#2563eb'};`;
    }else if(f.shape==='arch'){
      radius='999px 999px 14px 14px';wh='width:92px;height:116px;';
      borderStyle=`border:4px solid ${hasOutline?outlineColor:accentC};`;
    }else if(f.shape==='blob'){
      radius='58% 42% 55% 45% / 48% 56% 44% 52%';wh='width:98px;height:104px;';
      borderStyle=`border:4px solid ${hasOutline?outlineColor:'#fff'};`;shadow='box-shadow:0 8px 20px rgba(15,23,42,.22);';
    }else if(f.shape==='leaf'){
      radius='50% 10% 50% 10%';wh='width:96px;height:96px;';
      borderStyle=`border:4px solid ${hasOutline?outlineColor:accentC};`;
    }else if(f.shape==='ring'){
      radius='50%';wh='width:92px;height:92px;';
      borderStyle='border:0;';shadow=`box-shadow:0 0 0 4px #fff,0 0 0 7px ${hasOutline?outlineColor:accentC};`;
    }else if(f.shape==='squircle'){
      radius='34%';wh='width:96px;height:96px;';
      borderStyle=`border:4px solid ${hasOutline?outlineColor:'#fff'};`;shadow='box-shadow:0 6px 16px rgba(15,23,42,.2);';
    }else if(f.shape==='cut'){
      radius='0';wh='width:92px;height:112px;';
      clip='clip-path:polygon(0 0,76% 0,100% 20%,100% 100%,0 100%);';
      borderStyle=`border:0;border-left:5px solid ${hasOutline?outlineColor:accentC};`;
    }else if(f.shape==='pill'){
      radius='999px';wh='width:84px;height:118px;';
      borderStyle=`border:4px solid ${hasOutline?outlineColor:'#fff'};`;shadow='box-shadow:0 6px 16px rgba(15,23,42,.2);';
    }else if(f.shape==='polaroid'){
      radius='3px';wh='width:96px;height:112px;';
      borderStyle='border:6px solid #fff;border-bottom-width:18px;';shadow='box-shadow:0 8px 18px rgba(15,23,42,.28);transform:rotate(-2.5deg);';
    }else if(f.shape==='hex'){
      radius='0';wh='width:104px;height:104px;';
      clip='clip-path:polygon(25% 5%,75% 5%,100% 50%,75% 95%,25% 95%,0% 50%);';
      borderStyle=hasOutline?`border:4px solid ${outlineColor};`:'border:4px solid rgba(255,255,255,.9);';
    }else if(f.shape==='diamond'){
      radius='0';wh='width:104px;height:104px;';
      clip='clip-path:polygon(50% 0%,100% 50%,50% 100%,0% 50%);';
      borderStyle=hasOutline?`border:4px solid ${outlineColor};`:'border:4px solid rgba(255,255,255,.9);';
    }

    const PS={t52:1.3,t53:1.3,t54:1.15,t55:1.2,t56:1.25,t57:1.1,t40:1.25,t37:1.25,t34:1.25,t35:1.2,t36:1.2,t38:1.2,t39:1.15,t41:1.2};const k=PS[state.template]||1.15;wh=wh.replace(/(\d+)px/g,(m,n)=>Math.round(n*k)+'px');
    cls='';
    extraStyle=`overflow:hidden;flex-shrink:0;border-radius:${radius};${wh}${clip}${shadow}${borderStyle}`;
  }

  const imgStyle=`width:100%;height:100%;object-fit:cover;object-position:50% 50%;transform:translate(${tx}%,${ty}%) scale(${zoom})${state.photoFit.flip?' scaleX(-1)':''};transform-origin:50% 50%;`;

  return `<div class="cv-photo ${cls}${state.photo?' has-img':''}" style="${extraStyle}">${state.photo?`<img src="${state.photo}" alt="profile" style="${imgStyle}">`:'Profile Photo'}</div>`;
}
function contact(){const f=state.form;return `<div class="small">${[f.phone,f.email,f.address].filter(Boolean).map(esc).join('<br>')}</div>`}
const SEC_KEYS={'Summary':'sum','Experience':'exp','Education':'edu','Technical Skills':'tech','Soft Skills':'soft','Languages':'lang','Projects':'proj','Certifications':'cert','References':'refs','Key Achievements':'ach','Personal Information':'pers'};
