function fmtCnic(v){const d=String(v||'').replace(/\D/g,'').slice(0,13);if(d.length<=5)return d;if(d.length<=12)return d.slice(0,5)+'-'+d.slice(5);return d.slice(0,5)+'-'+d.slice(5,12)+'-'+d.slice(12)}
function setCnic(el){const v=fmtCnic(el.value);el.value=v;const d=v.replace(/\D/g,'').length;const h=document.getElementById('cnicHint');if(h)h.textContent=(d===0||d===13)?'':'CNIC has 13 digits (format 12345-1234567-1).';setField('form.cnic',v)}
