function personalFormHTML(){const f=state.form;const sel=(v,o)=>o.map(x=>`<option value="${x}" ${v===x?'selected':''}>${x||'Select'}</option>`).join('');return `<div class="formsec"><h3>Personal Information (optional)</h3><p class="muted small">Many employers in Pakistan ask for these details. Fill only what you want to show. Add your CNIC only if the employer specifically asks for it, because a CV may be shared with other people.</p><label class="pi-switch ${state.show.personal?'on':''}"><input type="checkbox" role="switch" ${state.show.personal?'checked':''} onchange="setShowFlag('personal',this.checked);this.parentNode.classList.toggle('on',this.checked);this.parentNode.querySelector('.pi-state').textContent=this.checked?'ON: shown on your CV':'OFF: hidden from your CV'"><span class="pi-track"><span class="pi-knob"></span></span><span class="pi-text"><b>Show Personal Information on my CV</b><span class="pi-state">${state.show.personal?'ON: shown on your CV':'OFF: hidden from your CV'}</span></span></label><div class="row"><div><label>Father's Name</label><input value="${esc(f.father)}" maxlength="80" oninput="setField('form.father',this.value)"></div><div><label>Date of Birth</label><input value="${esc(f.dob)}" maxlength="40" placeholder="e.g. 12 March 1998" oninput="setField('form.dob',this.value)"></div></div><div class="row"><div><label>CNIC Number</label><input value="${esc(f.cnic)}" maxlength="15" inputmode="numeric" autocomplete="off" placeholder="12345-1234567-1" oninput="setCnic(this)"><p class="muted small" id="cnicHint"></p></div><div><label>Marital Status</label>${maritalHTML()}</div></div><div class="row3"><div><label>Nationality</label><input value="${esc(f.nationality)}" maxlength="40" oninput="setField('form.nationality',this.value)"></div><div><label>Domicile</label><input value="${esc(f.domicile)}" maxlength="40" oninput="setField('form.domicile',this.value)"></div><div><label>Religion</label><input value="${esc(f.religion)}" maxlength="40" oninput="setField('form.religion',this.value)"></div></div></div>`}
function extraBlocksHTML(key,label,start,ph1,ph2,ph3){const arr=Array.isArray(state.form[key])?state.form[key]:[];return arr.map((x,i)=>`<div class="extra-block"><div class="extra-head"><label>${label} ${start+i}</label><button class="btn danger small" type="button" onclick="removeExtra('${key}',${i})">Remove</button></div><input placeholder="${ph1}" value="${esc(x.t)}" maxlength="200" oninput="setExtra('${key}',${i},'t',this.value)"><input placeholder="${ph2}" value="${esc(x.c)}" maxlength="200" oninput="setExtra('${key}',${i},'c',this.value)"><textarea placeholder="${ph3}" maxlength="2000" oninput="setExtra('${key}',${i},'d',this.value)">${esc(x.d)}</textarea></div>`).join('')}
