function useFreeDesign(){const back=state._back&&templates.find(x=>x.id===state._back&&!x.premium);if(back)backToFree();else setTemplate('t21')}
function exportBlockHTML(premium){const unlocked=customerUnlocked()||ownerMode;const T=tpl();const tip=`<details class="dl-help"><summary>PDF cut, blank page or colours missing? Read this</summary><p class="muted small">In the print window choose Paper size <b>A4</b>, Margins <b>None</b>, Scale <b>100%</b> and turn <b>Background graphics</b> on. If your browser still adds blank or cut pages, tell us which browser you use so we can fix it.</p></details>`;const P=BUSINESS.prices||{};
if(premium&&!unlocked)return `<div class="formsec dl"><h3>Unlock your premium CV</h3><p class="dl-design">Your design: <b>${esc(T.name)}</b> <span class="tag premium">Premium</span></p><p class="muted">You can design and preview for free. To download this design you need an access code. It takes 3 easy steps:</p>${P.show&&P.premium?`<p class="dl-price">Price: <b>${esc(P.premium)}</b></p>`:''}<div class="actions"><button class="btn pink big" onclick="openOrder()">Start order (3 easy steps)</button><button class="btn light" onclick="openOrder();orderStep(3)">I already have a code</button></div><ol class="dl-steps"><li><b>Pay</b><span>See the payment options (EasyPaisa, JazzCash, bank and more).</span></li><li><b>Send your order</b><span>One tap. Your CV details go with it, you do not type anything again.</span></li><li><b>Get your code</b><span>We check your payment and send the access code. Enter it here and download.</span></li></ol><p class="muted small">Do not want to pay? <button type="button" class="linkbtn" onclick="useFreeDesign()">Use a free design instead</button>. Your details stay safe.</p></div>`;
const badge=premium?'<span class="tag premium">Premium unlocked</span>':'<span class="tag">Free</span>';
return `<div class="formsec dl"><h3>Download your CV</h3><p class="dl-design">Your design: <b>${esc(T.name)}</b> ${badge}</p><ol class="dl-steps"><li><b>Check your CV</b><span>Look at the preview. On a phone, tap "View CV Preview".</span></li><li><b>Press Download PDF</b><span>A window opens.</span></li><li><b>Choose "Save as PDF"</b><span>Then press Save. Your CV file is ready.</span></li></ol><div class="actions"><button class="btn green big" onclick="exportPDF()">Download PDF</button><button class="btn dark" onclick="exportDocx()">Word (editable)</button><button class="btn light" onclick="exportWord()" id="wordBtn">Word as picture</button></div>${tip}${premium?'':`<p class="muted small">Want a more eye-catching design? <button type="button" class="linkbtn" onclick="openOrder()">See premium options</button></p>`}</div>`}
/* CV Health Check: simple rule-based checklist (not a score, not a promise about ATS results) */
function healthChecks(){const f=state.form,out=[],T=v=>String(v==null?'':v).trim(),add=(ok,t,tip)=>out.push({ok:!!ok,t,tip});
 const exps=[{t:f.exp1t,c:f.exp1c,d:f.exp1d},{t:f.exp2t,c:f.exp2c,d:f.exp2d}].concat(Array.isArray(f.expMore)?f.expMore:[]).filter(x=>x&&(T(x.t)||T(x.c)||T(x.d)));
 const edus=[{t:f.edu1t,c:f.edu1c,d:f.edu1d},{t:f.edu2t,c:f.edu2c,d:f.edu2d}].concat(Array.isArray(f.eduMore)?f.eduMore:[]).filter(x=>x&&(T(x.t)||T(x.c)||T(x.d)));
 add(T(f.name)&&T(f.phone)&&T(f.email),'Name, phone and email are filled in','Add your full name, a phone number and an email address so employers can contact you.');
 if(T(f.email))add(/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(T(f.email)),'Email address looks valid','Check the email address. It should look like name@example.com.');
 add(T(f.job),'Job title is added under your name','Add the job title you are applying for, for example "Accountant" or "IT Support Technician".');
 const sl=T(f.summary).length;add(sl>=150&&sl<=650,'Summary has a good length','Write a short summary of 3 to 4 lines (about 150 to 650 characters): your experience, main skills and goal.'+(sl>650?' Yours is long.':sl>0?' Yours is short.':''));
 if(f.stage!=='fresh')add(exps.length>0,'Work experience is added','Add your most recent job first. If you are a fresher, add an internship, training or a project instead.');
 if(exps.length){add(exps.every(x=>T(x.d).split(/\n+|(?<=[.!?])\s+/).filter(Boolean).length>=2),'Each job has at least 2 points','Describe each job in 2 to 5 short points, one duty or achievement per line.');
  add(exps.some(x=>/\d/.test(T(x.d))),'Results include numbers','Add numbers where you can, such as customers served, percentage improved or team size.')}
 add(edus.length>0,'Education is added','Add your latest qualification with the institute name.');
 const yr=x=>{const m=(T(x.t)+' '+T(x.c)+' '+T(x.d)).match(/\b(19|20)\d{2}\b/g);return m?Math.max.apply(null,m.map(Number)):0};
 const newestFirst=list=>{const y=list.map(yr).filter(Boolean);for(let i=1;i<y.length;i++)if(y[i]>y[i-1])return false;return true};
 if(edus.map(yr).filter(Boolean).length>=2)add(newestFirst(edus),'Education is listed newest first','List your latest qualification first (for example Intermediate before Matriculation), the way employers expect.');
 if(exps.map(yr).filter(Boolean).length>=2)add(newestFirst(exps),'Jobs are listed newest first','List your most recent job first and the older ones after it.');
 add((f.tech||[]).filter(x=>T(x&&x.name)).length>=5,'At least 5 skills are listed','List at least 5 skills that match the job you want.');
 add(T(f.lang),'Languages are added','Add the languages you speak, for example Urdu, English.');
 const all=[f.name,f.job,f.summary,f.projects,f.certs,f.refs,f.customBody].concat(exps.map(x=>[x.t,x.c,x.d].join(' ')),edus.map(x=>[x.t,x.c,x.d].join(' '))).join(' ');
 add(!/\[[^\]]*\]|lorem ipsum|\bxxx+\b|your name|company name/i.test(all),'No placeholder text left','Replace placeholder text such as [Institute], [Year] or "Company Name" with real details.');
 const pg=(document.querySelectorAll('#cvPreview .cvpage')||[]).length;if(pg>0)add(pg<=2,'CV length is 2 pages or less','Most employers prefer a CV of 1 to 2 pages. Shorten older jobs or remove less important points.');
 return out}
function healthHTML(){const c=healthChecks(),ok=c.filter(x=>x.ok).length,pct=Math.round(ok/c.length*100);
 return `<div class="formsec hc"><h3>CV Health Check</h3><p class="small"><b>${ok} of ${c.length}</b> checks passed</p><div class="hc-bar" role="img" aria-label="${ok} of ${c.length} checks passed"><span style="width:${pct}%"></span></div><ul class="hc-list">${c.map(x=>`<li class="${x.ok?'hc-ok':'hc-todo'}"><span class="hc-ico" aria-hidden="true">${x.ok?'✓':'!'}</span><div><b>${esc(x.t)}</b>${x.ok?'':`<div class="small muted">${esc(x.tip)}</div>`}</div></li>`).join('')}</ul><button class="btn light" onclick="fullRenderKeepPosition()">Check again</button><p class="small"><b>Before you download:</b> read your CV once more and fix any spelling mistakes. This checklist cannot check spelling for you.</p><p class="muted small">This is a simple checklist based on common CV practice. It does not guarantee interviews or how any employer's software will read your CV.</p></div>`}
